package com.bank.payout.service;

import java.util.logging.Logger;

// Decides whether payouts can be split into two equal-sum halves (subset-sum DP).
public class PayoutSplitService {
    private static final Logger log = Logger.getLogger(PayoutSplitService.class.getName());

    public boolean canSplitEqually(int[] amounts) {
        int total = 0;
        for (int a : amounts) total += a;
        if (total % 2 != 0) {
            log.info("Total is odd; equal split impossible");
            return false;                      // odd total cannot split evenly
        }
        int target = total / 2;
        boolean[] dp = new boolean[target + 1];
        dp[0] = true;                          // empty subset reaches sum 0
        for (int num : amounts) {
            for (int t = target; t >= num; t--) {   // high → low ⇒ each item once
                dp[t] = dp[t] || dp[t - num];
            }
            if (dp[target]) break;             // early exit once reachable
        }
        final boolean ans = dp[target];
        log.info(() -> "Equal split possible = " + ans);
        return dp[target];
    }
}
