package com.bank.payout;

import com.bank.payout.service.PayoutSplitService;
import java.util.logging.Logger;

public class PayoutSplitApplication {
    private static final Logger log = Logger.getLogger(PayoutSplitApplication.class.getName());

    public static void main(String[] args) {
        PayoutSplitService service = new PayoutSplitService();
        int[] payouts = {15, 5, 10, 20};      // payout amounts (in thousands)
        boolean canSplit = service.canSplitEqually(payouts);
        log.info("Can payouts be split equally between two tellers? " + canSplit);
    }
}
